INSERT INTO public.daily_quizzes(quiz_date,payload) VALUES
  ('2026-10-03','{"id":"daily-quiz-2026-10-03","theme":"Manejo del Estrés","subtitle":"Sobreviviendo la presión juntos","questions":[{"id":"q-2026-10-03-0","question":"Cuando estás muy estresado/a, tu forma de actuar cambia a:","options":["Me aíslo y me vuelvo más callado/a","Me pongo muy irritable y salto por cualquier cosa","Empiezo a limpiar y ordenar todo compulsivamente","Como mucho más o puro azúcar por ansiedad"]},{"id":"q-2026-10-03-1","question":"Si los dos estamos pasando por una semana terrible al mismo tiempo:","options":["Chocamos y discutimos más fácilmente","Nos unimos más y somos un equipo de supervivencia","Nos vemos menos para no traspasarnos mala onda","Lloramos juntos comiendo chatarra"]},{"id":"q-2026-10-03-2","question":"¿Cuál es tu forma de ''botar'' estrés que yo más noto?","options":["Ponerte a jugar videojuegos por horas","Dormir siestas muy largas","Quejarte y hablar mucho rápido","Hacer ejercicio o salir a caminar"]},{"id":"q-2026-10-03-3","question":"Si me ves colapsado/a por algo de trabajo/estudios que no me sale:","options":["Me ofreces ayuda práctica (revisar texto, hacer un esquema)","Me obligas a cerrar el computador un rato y descansar","Me traes un café o tecito sin que te lo pida","Me dices frases motivadoras para no rendirme"]},{"id":"q-2026-10-03-4","question":"El mejor escape de fin de semana para bajar el estrés sería:","options":["Literalmente no salir de la cama todo el fin de semana","Irnos a la naturaleza a respirar aire puro","Ir a un lugar donde haya buena comida y copetes","Hacer algo extremo o diferente (parque de diversiones, subir un cerro pesado)"]}]}'::JSONB),
  ('2026-10-04','{"id":"daily-quiz-2026-10-04","theme":"Nuestro primer hogar","subtitle":"Un espacio que se sienta de los dos","questions":[{"question":"¿Qué rincón reservarías primero en nuestro hogar?","options":["Un sillón para conversar","Una mesa para comer juntos","Un espacio para nuestros hobbies","Un balcón lleno de plantas"],"id":"series-1-0-0"},{"question":"¿Qué haría que nuestra casa se sintiera nuestra desde el primer día?","options":["Fotos de nuestros momentos","Cocinar nuestra primera comida","Elegir juntos la música","Invitar a alguien querido"],"id":"series-1-0-1"},{"question":"¿Cómo elegirías un objeto cuando nuestros gustos son distintos?","options":["Buscar una tercera opción","Turnarnos para elegir","Probarlo antes de decidir","Mezclar ambos estilos"],"id":"series-1-0-2"},{"question":"¿Qué pequeño ritual te gustaría al llegar a casa?","options":["Un abrazo sin apuro","Contarnos una cosa del día","Preparar algo para tomar","Descansar juntos en silencio"],"id":"series-1-0-3"},{"question":"¿Qué preferirías construir con nuestras manos?","options":["Un estante para recuerdos","Una huerta pequeña","Un álbum de fotos","Una lámpara para nuestro rincón"],"id":"series-1-0-4"}]}'::JSONB),
  ('2026-10-05','{"id":"daily-quiz-2026-10-05","theme":"Cuidarnos sin adivinar","subtitle":"Aprender a pedir lo que necesitamos","questions":[{"question":"¿Cómo te gustaría pedirme compañía en un día difícil?","options":["Decirlo directamente","Mandar una palabra clave","Pedir un abrazo","Proponer salir un rato"],"id":"series-1-1-0"},{"question":"¿Qué pregunta te ayuda más cuando estás sobrepasado/a?","options":["¿Quieres que te escuche?","¿Te ayudo con algo concreto?","¿Necesitas estar a solas?","¿Hacemos una pausa juntos?"],"id":"series-1-1-1"},{"question":"¿Cómo prefieres que te recuerde descansar?","options":["Con un mensaje amable","Preparando una pausa juntos","Preguntando si puedo ayudarte","Esperando a que tú lo pidas"],"id":"series-1-1-2"},{"question":"¿Qué gesto te hace sentir acompañado/a durante una espera larga?","options":["Que me tomen la mano","Que me distraigan conversando","Que se queden a mi lado","Que ayuden con lo pendiente"],"id":"series-1-1-3"},{"question":"¿Cómo sabríamos que un consejo no es lo que necesitas?","options":["Lo diría al principio","Usaríamos una señal acordada","Me lo preguntarías primero","Lo conversaría después"],"id":"series-1-1-4"}]}'::JSONB),
  ('2026-10-06','{"id":"daily-quiz-2026-10-06","theme":"Un día sin agenda","subtitle":"Disfrutar cuando no hay nada que cumplir","questions":[{"question":"Si amanecemos con un día completamente libre, ¿qué harías primero?","options":["Mirar cómo está el clima","Preparar desayuno largo","Seguir descansando","Elegir una aventura pequeña"],"id":"series-1-2-0"},{"question":"¿Qué plan improvisado elegirías con poco dinero?","options":["Recorrer un barrio nuevo","Hacer un picnic casero","Visitar una biblioteca","Cocinar con lo que hay"],"id":"series-1-2-1"},{"question":"¿Qué harías si nuestro paseo termina antes de lo esperado?","options":["Buscar otro lugar cerca","Volver y descansar","Inventar un juego en el camino","Comprar algo rico para compartir"],"id":"series-1-2-2"},{"question":"¿Cómo te gustaría decidir un plan espontáneo?","options":["Cada uno propone una idea","Elegimos al azar","Uno sorprende al otro","Caminamos y vemos qué aparece"],"id":"series-1-2-3"},{"question":"¿Qué haría especial un domingo sin salir?","options":["Hacer algo creativo","Almorzar sin mirar la hora","Conversar de nuestros sueños","Cambiar de lugar los muebles"],"id":"series-1-2-4"}]}'::JSONB),
  ('2026-10-07','{"id":"daily-quiz-2026-10-07","theme":"Celebrar lo pequeño","subtitle":"Victorias que también merecen un abrazo","questions":[{"question":"¿Cómo celebrarías que por fin terminé algo que postergaba?","options":["Con mi comida favorita","Diciendo que estás orgulloso/a","Con un paseo corto","Con una nota sorpresa"],"id":"series-1-3-0"},{"question":"¿Qué logro cotidiano te gustaría que yo notara más?","options":["Que me atreví a pedir ayuda","Que mantuve un hábito","Que puse un límite","Que aprendí algo difícil"],"id":"series-1-3-1"},{"question":"¿Dónde guardarías nuestras pequeñas victorias del mes?","options":["En un frasco con papelitos","En una nota compartida","En fotos espontáneas","En una conversación al cerrar el mes"],"id":"series-1-3-2"},{"question":"Si algo no salió perfecto pero lo intentaste, ¿qué te gustaría escuchar?","options":["Vi cuánto te esforzaste","Vamos a probar de otra forma","Hoy ya avanzaste algo","Podemos descansar y seguir mañana"],"id":"series-1-3-3"},{"question":"¿Qué tradición inventarías para los avances de los dos?","options":["Un brindis con lo que haya","Un baile de treinta segundos","Una foto haciendo una pose","Elegir el postre del día"],"id":"series-1-3-4"}]}'::JSONB),
  ('2026-10-08','{"id":"daily-quiz-2026-10-08","theme":"Salir de nuestra burbuja","subtitle":"Compartir también con quienes queremos","questions":[{"question":"¿Qué plan harías para conocer mejor a mis amigos?","options":["Una comida pequeña","Un juego de mesa","Un paseo al aire libre","Una conversación de a uno"],"id":"series-1-4-0"},{"question":"Si una reunión me pone nervioso/a, ¿cómo me acompañarías?","options":["Presentándome con calma","Quedándote cerca al principio","Acordando una señal para salir","Contándome quién estará antes"],"id":"series-1-4-1"},{"question":"¿Qué te gustaría que nuestra gente cercana supiera de nosotros?","options":["Lo bien que nos apoyamos","Nuestro sentido del humor","Los proyectos que tenemos","Que cuidamos nuestros espacios"],"id":"series-1-4-2"},{"question":"¿Cómo repartirías un fin de semana con visitas a ambas familias?","options":["Un día para cada una","Alternando los fines de semana","Organizando una reunión conjunta","Decidiendo según la ocasión"],"id":"series-1-4-3"},{"question":"¿Qué límite cuidarías cuando nos preguntan cosas muy personales?","options":["Responder solo lo que acordamos","Cambiar de tema con humor","Decir que preferimos guardarlo","Conversarlo en privado después"],"id":"series-1-4-4"}]}'::JSONB),
  ('2026-10-09','{"id":"daily-quiz-2026-10-09","theme":"Aprender algo juntos","subtitle":"Ser principiantes también puede ser una cita","questions":[{"question":"¿Qué taller probarías conmigo aunque no tengamos experiencia?","options":["Cerámica","Baile","Cocina de otro país","Fotografía"],"id":"series-1-5-0"},{"question":"Si a uno le resulta mucho más fácil una actividad, ¿qué ayudaría?","options":["Aprender al ritmo del otro","Separar retos por dificultad","Reírnos de nuestros intentos","Elegir otra actividad compartida"],"id":"series-1-5-1"},{"question":"¿Qué te gustaría que hiciera cuando te equivocas aprendiendo?","options":["Animarte a intentarlo otra vez","Mostrarte cómo lo hice","Preguntar si quieres ayuda","Dejarte resolverlo a tu manera"],"id":"series-1-5-2"},{"question":"¿Cómo guardarías el recuerdo de nuestra primera clase?","options":["Con una foto del resultado","Conservando el primer intento","Escribiendo lo más divertido","Celebrando con una comida"],"id":"series-1-5-3"},{"question":"¿Qué proyecto de aprendizaje mantendrías por un mes?","options":["Una receta nueva por semana","Aprender frases de un idioma","Dibujar unos minutos al día","Practicar un instrumento juntos"],"id":"series-1-5-4"}]}'::JSONB),
  ('2026-10-10','{"id":"daily-quiz-2026-10-10","theme":"Nuestros ritmos","subtitle":"Convivir con energías distintas","questions":[{"question":"Si yo quiero salir y tú necesitas descanso, ¿qué propondrías?","options":["Un plan corto y tranquilo","Salir por separado ese día","Descansar primero y decidir","Dejar la salida para mañana"],"id":"series-1-6-0"},{"question":"¿Cuándo te resulta más fácil tener una conversación importante?","options":["Después de desayunar","Durante una caminata","Al terminar las tareas del día","Cuando acordamos un momento"],"id":"series-1-6-1"},{"question":"¿Qué señal te gustaría usar para pedir una pausa sin preocuparme?","options":["Decir vuelvo en un rato","Un abrazo y una explicación","Un mensaje breve","Una frase que acordemos"],"id":"series-1-6-2"},{"question":"¿Qué actividad compartirías aunque estemos con energías diferentes?","options":["Leer uno al lado del otro","Escuchar un álbum","Preparar una comida simple","Mirar el paisaje desde un banco"],"id":"series-1-6-3"},{"question":"¿Cómo te gustaría retomar un plan que tuvimos que cancelar por cansancio?","options":["Fijar otra fecha enseguida","Esperar a sentirnos mejor","Elegir una versión más sencilla","Preguntar qué sigue dando ganas"],"id":"series-1-6-4"}]}'::JSONB),
  ('2026-10-11','{"id":"daily-quiz-2026-10-11","theme":"Un presupuesto para soñar","subtitle":"Elegir qué vale la pena para nosotros","questions":[{"question":"Si juntamos un pequeño ahorro compartido, ¿para qué lo usarías primero?","options":["Una escapada","Mejorar nuestro espacio","Una experiencia nueva","Guardar un colchón para imprevistos"],"id":"series-1-7-0"},{"question":"¿Cómo conversarías sobre un gasto que te parece demasiado?","options":["Explicando qué me preocupa","Comparando alternativas","Poniendo un límite juntos","Preguntando por qué es importante"],"id":"series-1-7-1"},{"question":"¿Qué cita económica repetirías sin aburrirte?","options":["Desayuno preparado en casa","Caminar con algo rico","Noche de juegos inventados","Visitar una exposición gratuita"],"id":"series-1-7-2"},{"question":"¿Qué prefieres al elegir un regalo con presupuesto limitado?","options":["Algo hecho por mí","Algo útil que necesites","Una experiencia compartida","Una carta y un detalle pequeño"],"id":"series-1-7-3"},{"question":"¿Cómo elegirías entre dos metas de ahorro nuestras?","options":["Priorizar la más cercana","Repartir entre ambas","Alternar cada mes","Conversar cuál nos ilusiona más"],"id":"series-1-7-4"}]}'::JSONB),
  ('2026-10-12','{"id":"daily-quiz-2026-10-12","theme":"Nuestros espacios propios","subtitle":"Estar juntos y seguir siendo nosotros","questions":[{"question":"¿Qué hobby te gustaría que yo conociera sin tener que practicarlo?","options":["Uno creativo","Uno deportivo","Uno de colección","Uno que todavía quiero descubrir"],"id":"series-1-8-0"},{"question":"¿Cómo te gustaría contarme que necesitas una tarde para ti?","options":["Decirlo al organizar la semana","Avisarme ese mismo día","Invitarme a hacer mi propio plan","Proponer vernos después"],"id":"series-1-8-1"},{"question":"¿Qué te gustaría que preguntara sobre tus proyectos personales?","options":["Qué parte te entusiasma","En qué puedo apoyarte","Qué has aprendido","Cómo te gustaría celebrarlo"],"id":"series-1-8-2"},{"question":"¿Cómo compartirías un logro que conseguiste por tu cuenta?","options":["Con una llamada","Con una foto del momento","Contándolo al vernos","Guardando una sorpresa para después"],"id":"series-1-8-3"},{"question":"¿Qué balance te gustaría en una semana muy ocupada?","options":["Un encuentro largo","Varios ratitos cortos","Mensajes y un plan al final","Elegir según nuestras energías"],"id":"series-1-8-4"}]}'::JSONB),
  ('2026-10-13','{"id":"daily-quiz-2026-10-13","theme":"Cuando algo cambia","subtitle":"Acompañarnos en etapas nuevas","questions":[{"question":"Si cambio de trabajo o estudios, ¿qué apoyo te pediría primero?","options":["Escuchar mis nervios","Ayudarme a organizar","Celebrar el nuevo comienzo","Tener paciencia con mis horarios"],"id":"series-1-9-0"},{"question":"¿Qué conservarías si nuestra rutina cambia por completo?","options":["Una llamada a cierta hora","Una comida semanal","Un mensaje al despertar","Un espacio para contarnos cómo vamos"],"id":"series-1-9-1"},{"question":"¿Cómo hablarías de una decisión grande que nos afecta?","options":["Con tiempo para pensarlo","Con una lista de opciones","Conversando caminando","Buscando un momento sin distracciones"],"id":"series-1-9-2"},{"question":"¿Qué te tranquiliza más frente a un futuro incierto?","options":["Tener un primer paso","Sentir que somos un equipo","Conocer las alternativas","Saber que podemos cambiar de plan"],"id":"series-1-9-3"},{"question":"¿Cómo te gustaría revisar si una nueva rutina nos funciona?","options":["Una charla semanal","Preguntándonos al terminar el día","Anotando lo que cuesta","Probándola un mes antes de decidir"],"id":"series-1-9-4"}]}'::JSONB),
  ('2026-10-14','{"id":"daily-quiz-2026-10-14","theme":"Nuestra cápsula del tiempo","subtitle":"Dejarle pistas a nuestro yo del futuro","questions":[{"question":"¿Qué pondrías primero en una cápsula del tiempo nuestra?","options":["Una carta","Una foto espontánea","Un objeto de una cita","Una lista de sueños actuales"],"id":"series-1-10-0"},{"question":"¿Qué pregunta le harías a nuestro yo de cinco años más?","options":["¿Qué sueño cumplimos?","¿Qué costumbre conservamos?","¿Qué nos sorprendió?","¿De qué seguimos riéndonos?"],"id":"series-1-10-1"},{"question":"¿Qué sonido guardarías de esta etapa?","options":["Nuestras risas","Una conversación cotidiana","El ruido de un lugar especial","Una canción cantada por nosotros"],"id":"series-1-10-2"},{"question":"¿Qué detalle de hoy crees que podríamos olvidar con los años?","options":["Las frases que inventamos","Los lugares por donde caminamos","Cómo nos organizamos para vernos","Los pequeños favores que hacemos"],"id":"series-1-10-3"},{"question":"¿Cuándo abrirías la cápsula del tiempo?","options":["En un aniversario","Al mudarnos juntos","Después de cumplir una meta","En una fecha elegida al azar"],"id":"series-1-10-4"}]}'::JSONB),
  ('2026-10-15','{"id":"daily-quiz-2026-10-15","theme":"Crear nuestras tradiciones","subtitle":"Costumbres que nacen de los dos","questions":[{"question":"¿Qué tradición inventarías para el primer día de cada mes?","options":["Elegir una cita","Escribir un deseo","Probar una comida","Tomar una foto en el mismo lugar"],"id":"series-1-11-0"},{"question":"¿Cómo harías especial una fecha que nadie más celebra?","options":["Con un nombre propio","Con un ritual pequeño","Con una sorpresa","Recordando por qué importa"],"id":"series-1-11-1"},{"question":"¿Qué harías con una tradición que ya no disfrutamos?","options":["Cambiarla juntos","Reemplazarla por otra","Dejarla descansar un tiempo","Conservar solo una parte"],"id":"series-1-11-2"},{"question":"¿Qué ritual de despedida te gustaría tener?","options":["Un abrazo largo","Una frase nuestra","Una foto divertida","Acordar el próximo encuentro"],"id":"series-1-11-3"},{"question":"¿Qué tradición llevarías a cualquier ciudad donde vivamos?","options":["Pasear sin rumbo un día al mes","Desayunar juntos el domingo","Escribirnos notas","Buscar un lugar favorito para conversar"],"id":"series-1-11-4"}]}'::JSONB),
  ('2026-10-16','{"id":"daily-quiz-2026-10-16","theme":"Una cita con los sentidos","subtitle":"Descubrir detalles que suelen pasar de largo","questions":[{"question":"¿Qué aroma elegirías para recordar una cita nuestra?","options":["Pan recién hecho","Flores después de la lluvia","Café","El aire cerca del mar"],"id":"series-1-12-0"},{"question":"¿Qué textura te gustaría sumar a nuestro rincón de descanso?","options":["Una manta suave","Almohadones de lino","Una alfombra mullida","Madera cálida"],"id":"series-1-12-1"},{"question":"¿Qué sabor explorarías conmigo en una degustación?","options":["Chocolate de distintos orígenes","Frutas que no conocemos","Quesos","Infusiones"],"id":"series-1-12-2"},{"question":"¿Qué sonido te gustaría escuchar juntos sin hacer nada más?","options":["Lluvia en el techo","Olas","Pájaros al amanecer","Una pieza instrumental"],"id":"series-1-12-3"},{"question":"¿Qué detalle buscarías en un paseo de observación?","options":["Colores de las fachadas","Sombras y reflejos","Plantas entre las veredas","Personas haciendo cosas cotidianas"],"id":"series-1-12-4"}]}'::JSONB),
  ('2026-10-17','{"id":"daily-quiz-2026-10-17","theme":"Resolver como equipo","subtitle":"Pequeños imprevistos sin perder la complicidad","questions":[{"question":"Si nos perdemos caminando por una ciudad nueva, ¿qué harías?","options":["Consultar un mapa","Preguntar a alguien","Disfrutar el desvío","Volver al último lugar conocido"],"id":"series-1-13-0"},{"question":"Si una reserva se cancela a última hora, ¿qué te ayudaría?","options":["Buscar un plan alternativo","Tomarnos unos minutos","Reírnos del imprevisto","Decidir si queremos volver a casa"],"id":"series-1-13-1"},{"question":"¿Cómo repartirías una tarea que ninguno quiere hacer?","options":["Hacerla juntos","Turnarnos","Dividirla en partes","Compensarla con otra tarea"],"id":"series-1-13-2"},{"question":"Si llegamos tarde por un problema inesperado, ¿qué priorizarías?","options":["Avisar a quien espera","Encontrar la salida más simple","Evitar culparnos","Revisar si todavía vale la pena ir"],"id":"series-1-13-3"},{"question":"Después de resolver un lío juntos, ¿cómo cerrarías el día?","options":["Con algo rico","Contando lo que aprendimos","Descansando sin hablar del tema","Celebrando que lo resolvimos"],"id":"series-1-13-4"}]}'::JSONB),
  ('2026-10-18','{"id":"daily-quiz-2026-10-18","theme":"Decir gracias de verdad","subtitle":"Reconocer lo que el otro hace","questions":[{"question":"¿Qué agradecimiento te llega más?","options":["Que nombren el gesto concreto","Una nota que pueda guardar","Un abrazo","Que me devuelvan el cuidado otro día"],"id":"series-1-14-0"},{"question":"¿Qué ayuda silenciosa te gustaría que se reconociera?","options":["Organizar los planes","Recordar fechas importantes","Escuchar con atención","Resolver detalles prácticos"],"id":"series-1-14-1"},{"question":"¿Cómo agradecerías que te acompañe en algo que no disfruto tanto?","options":["Preguntando qué plan quiero después","Diciéndome por qué fue importante","Preparando un detalle","Ayudándome en algo mío"],"id":"series-1-14-2"},{"question":"¿Cuándo prefieres recibir un reconocimiento?","options":["En el momento","En privado al terminar el día","En una sorpresa posterior","Cuando sale naturalmente"],"id":"series-1-14-3"},{"question":"¿Qué gesto te gustaría agradecerme hoy?","options":["Mi paciencia","Mi presencia","Mi iniciativa","Mi forma de hacerte reír"],"id":"series-1-14-4"}]}'::JSONB),
  ('2026-10-19','{"id":"daily-quiz-2026-10-19","theme":"Una aventura cerca","subtitle":"Mirar nuestro entorno con ojos nuevos","questions":[{"question":"¿Qué lugar cotidiano convertirías en una pequeña aventura?","options":["Una feria","Un parque de otro barrio","Una estación que no conocemos","Un cerro cercano"],"id":"series-1-15-0"},{"question":"¿Qué misión nos pondrías durante un paseo?","options":["Encontrar tres cosas bonitas","Probar algo que nunca pedimos","Tomar fotos de un mismo color","Descubrir una historia del lugar"],"id":"series-1-15-1"},{"question":"¿Qué preferirías llevar para una salida corta?","options":["Un termo","Una cámara","Un cuaderno","Una manta"],"id":"series-1-15-2"},{"question":"¿Cómo elegirías el destino de una microaventura?","options":["Mirando el mapa sin buscar reseñas","Siguiendo una recomendación","Eligiendo por el nombre","Visitando un lugar pendiente"],"id":"series-1-15-3"},{"question":"¿Qué recuerdo traerías de una aventura cercana?","options":["Una postal dibujada","Una foto de un detalle","Una nueva receta","Una anécdota escrita"],"id":"series-1-15-4"}]}'::JSONB),
